/* ---------- Agent lanes ---------- */
/* each agent has its own hue (--c, with its tint --cb): its badge, its track, its tag and its stretch of the relay line that
   joins the badges. A hand-off sends a light down that line from one agent to the next, and the stretch it crossed stays lit */
.aln{padding:var(--s-2)}
/* on a card the lanes sit centred in the room kept for their tallest moment, and glide as a hand-off line opens and shuts */
.stage-in:has(>.aln){display:flex;flex-direction:column;justify-content:center}
.aln-h{display:flex;align-items:center;gap:10px;padding:var(--s-2) 10px 10px}
.aln-ic{color:var(--fg2);display:grid;transition:color .3s}
.aln.fin .aln-ic{color:var(--ok)}
.aln-t{font-weight:500}
.aln-m{font-size:12.5px}
.aln-ct{font-size:12.5px;color:var(--muted);margin-right:auto;white-space:nowrap}
.aln-ct::before{content:"·";margin-right:6px}
.aln-rows{position:relative}
.aln-rows>*{position:relative}
.aln-lane{border-radius:14px;transition:background .3s}
@media (hover:hover) and (pointer:fine){.aln-lane:hover{background:var(--row)}}
/* the lane at work carries a wash of its hue from the left */
.aln-lane[data-s="working"]{background:linear-gradient(90deg,color-mix(in srgb,var(--c) 8%,transparent),transparent 72%)}
@media (hover:hover) and (pointer:fine){.aln-lane[data-s="working"]:hover{background:linear-gradient(90deg,color-mix(in srgb,var(--c) 8%,transparent),transparent 72%),var(--row)}}
/* the relay line runs from badge to badge, through the lanes and the hand-offs between them, and stops short of each badge */
.aln-rows>*::before{content:"";position:absolute;left:26px;width:2px;top:0;bottom:0;border-radius:1px;background:var(--line);transition:background .5s var(--ease);pointer-events:none}
.aln-lane::before{top:48px}
.aln-lane:last-child::before{display:none}
.aln-lane::after{content:"";position:absolute;left:26px;width:2px;top:0;height:6px;border-radius:1px;background:var(--line);transition:background .5s var(--ease);pointer-events:none}
.aln-lane:first-child::after{display:none}
.aln-lane.sent::before{background:linear-gradient(var(--c),color-mix(in srgb,var(--c) 45%,var(--line)))}
.aln-lane.got::after{background:var(--c)}
.aln-hf.lit::before{background:linear-gradient(color-mix(in srgb,var(--from) 45%,var(--line)),var(--to))}
.aln-row{display:grid;grid-template-columns:34px minmax(0,1.2fr) minmax(0,1fr) auto;align-items:center;gap:var(--s-3);width:100%;padding:10px;text-align:left}
.aln-av{position:relative;width:34px;height:34px;border-radius:11px;display:grid;place-items:center;color:var(--c);background:var(--cb);transition:color .4s,background .4s}
.aln-av::before{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none}
.aln-lane[data-s="working"] .aln-av{animation:alnbreathe 2.4s var(--ease-io) infinite}
@keyframes alnbreathe{0%,100%{box-shadow:0 0 0 0 color-mix(in srgb,var(--c) 0%,transparent)}50%{box-shadow:0 0 0 4px color-mix(in srgb,var(--c) 18%,transparent)}}
/* the badge that takes a hand-off rings once as the light reaches it */
.aln-av.ping::before{animation:alnping .9s var(--ease)}
@keyframes alnping{from{box-shadow:0 0 0 0 color-mix(in srgb,var(--c) 50%,transparent)}to{box-shadow:0 0 0 12px color-mix(in srgb,var(--c) 0%,transparent)}}
/* a finished agent's badge fills with its hue */
.aln-lane[data-s="done"] .aln-av{background:var(--c);color:var(--surface)}
.aln-who{min-width:0}
.aln-n{display:block;font-weight:500;font-size:13.5px}
.aln-a{display:block;font-size:12.5px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.aln-a.live{color:var(--fg2)}
/* the track: one part a step. Finished parts are solid, the one in hand fills as the agent works, with a light running along it */
.aln-tr{display:flex;gap:3px}
.aln-tr i{flex:1;height:8px;border-radius:4px;background:color-mix(in srgb,var(--c) 13%,var(--line));position:relative;overflow:hidden}
.aln-tr i::after{content:"";position:absolute;inset:0;border-radius:inherit;background:var(--c);transform:scaleX(var(--p,0));transform-origin:left;transition:transform .25s linear}
.aln-tr i.on::after{transform:scaleX(1);transition:transform .5s var(--ease)}
.aln-tr i.run::after{background:linear-gradient(90deg,var(--c) 0 30%,color-mix(in srgb,var(--c) 30%,var(--surface)) 50%,var(--c) 70% 100%) 0 0/250% 100%;animation:alnsheen 1.6s linear infinite}
/* given no step progress, the part in hand fills part way and keeps its light */
.aln-tr i.run.ind::after{transform:scaleX(.6);transition:transform 2.4s var(--ease)}
@keyframes alnsheen{from{background-position:100% 0}to{background-position:-150% 0}}
.aln-st{min-width:92px;display:flex;justify-content:flex-end}
.aln-tg{background:var(--cb);color:var(--c)}
.aln-tg .spin{width:9px;height:9px}
.aln-det{padding:0 10px 10px 56px;font-size:12.5px;color:var(--fg2)}
.aln-det div{display:flex;align-items:center;gap:var(--s-2);padding:3px 0}
.aln-det div::before{content:"";width:5px;height:5px;border-radius:50%;background:var(--c);flex:none}
.aln-det .muted{margin-left:auto}
/* a hand-off opens a line between the lanes, glides the lanes below down and closes again */
.aln-hf{transition-duration:var(--t-slow)}
.aln-hand{padding:6px 10px 6px 56px;font-size:12.5px;line-height:18px;color:var(--fg2)}
.aln-hand b{font-weight:500}
.aln-hand .f{color:var(--from)}.aln-hand .t{color:var(--to)}
/* the light that carries the work down the line: a bright head with a tail in the sender's hue */
.aln-pk{position:absolute;left:27px;top:0;width:8px;height:8px;margin:-4px 0 0 -4px;border-radius:50%;background:var(--to);box-shadow:0 0 0 3px color-mix(in srgb,var(--to) 22%,transparent),0 0 12px 2px color-mix(in srgb,var(--to) 45%,transparent);pointer-events:none;z-index:2;opacity:0}
.aln-pk::before{content:"";position:absolute;left:3px;bottom:4px;width:2px;height:30px;border-radius:1px;background:linear-gradient(transparent,var(--from))}
@media (max-width:600px){
  .aln-row{grid-template-columns:34px minmax(0,1fr) auto;row-gap:var(--s-2)}
  .aln-tr{grid-column:2 / -1;grid-row:2}
  .aln-lane::before{top:48px}
  .aln-ct{display:none}
  .aln-m{margin-right:auto}
}
@media (max-width:400px){.aln-ic{display:none}}
:root:not([data-style="soft"]) .aln-rows>*:not(:where([data-style="soft"],[data-style="soft"] *))::before,:root:not([data-style="soft"]) .aln-lane:not(:where([data-style="soft"],[data-style="soft"] *))::after{width:1px;left:26.5px;background:repeating-linear-gradient(var(--rail) 0 3px,transparent 3px 6px)}
:root:not([data-style="soft"]) .aln-lane.sent:not(:where([data-style="soft"],[data-style="soft"] *))::before,:root:not([data-style="soft"]) .aln-lane.got:not(:where([data-style="soft"],[data-style="soft"] *))::after{background:var(--c)}
:root:not([data-style="soft"]) .aln-hf.lit:not(:where([data-style="soft"],[data-style="soft"] *))::before{background:var(--to)}
:root:not([data-style="soft"]) .aln-av:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--c) 35%,transparent)}
:root:not([data-style="soft"]) .aln-lane[data-s="working"] .aln-av:not(:where([data-style="soft"],[data-style="soft"] *)){animation:alnbp 1.1s steps(1,end) infinite}
@keyframes alnbp{0%,55%{box-shadow:inset 0 0 0 1px var(--c)}56%,100%{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--c) 35%,transparent)}}
:root:not([data-style="soft"]) .aln-lane[data-s="working"]:not(:where([data-style="soft"],[data-style="soft"] *)){background:color-mix(in srgb,var(--c) 5%,transparent)}
:root:not([data-style="soft"]) .aln-tr i:not(:where([data-style="soft"],[data-style="soft"] *)){height:6px}
:root:not([data-style="soft"]) .aln-tr i.run:not(:where([data-style="soft"],[data-style="soft"] *))::after{background:repeating-linear-gradient(135deg,var(--c) 0 4px,color-mix(in srgb,var(--c) 55%,var(--surface)) 4px 7px);animation:none}
:root:not([data-style="soft"]) .aln-pk:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:none;width:7px;height:7px;margin:-3px 0 0 -3px}
:root:not([data-style="soft"]) .aln-pk:not(:where([data-style="soft"],[data-style="soft"] *))::before{width:1px}
:root:not([data-style="soft"]) .aln-av.ping:not(:where([data-style="soft"],[data-style="soft"] *))::before{animation:alnpingbp .6s steps(3,end)}
@keyframes alnpingbp{from{box-shadow:0 0 0 1px var(--c)}to{box-shadow:0 0 0 7px transparent}}

DM.def('agent-lanes', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{users}', I('users')).replace('{pause}', I('pause','xs'));
  // each agent has a hue of its own (t names the palette slot): its badge, its track, its tag and its stretch of the relay line
  const L = [
    { n:'Researcher', ic:'search', t:'pb', acts:['Reading competitor sites','Comparing 5 pricing pages','Writing the brief'], log:['Read stripe.com/pricing','Read linear.app/pricing','Noted 3 patterns'] },
    { n:'Designer', ic:'palette', t:'pl', wait:'Waiting for the brief', acts:['Laying out pricing cards','Setting type and spacing','Exporting frames'], log:['Made 3 card variants','Applied spacing tokens','Exported 4 frames'] },
    { n:'Reviewer', ic:'eye', t:'pm', wait:'Waiting for the designer', acts:['Checking contrast','Checking copy','Signing off'], log:['Contrast passes AA','Fixed 2 lines of copy','Approved'] }
  ];
  const root = $('.aln', r), rows = $('.aln-rows', r), ct = $('.aln-ct', r), STEPS = L.length * 3;
  L.forEach(l => {
    l.el = html(`<div class="aln-lane" data-s="queued" style="--c:var(--${l.t});--cb:var(--${l.t}-bg)"><button class="aln-row" aria-expanded="false"><span class="aln-av">${I(l.ic)}</span><span class="aln-who"><span class="aln-n">${l.n}</span><span class="aln-a">${l.wait || 'Queued'}</span></span><span class="aln-tr" aria-hidden="true"><i></i><i></i><i></i></span><span class="aln-st"><span class="tag">Queued</span></span></button><div class="fold shut"><div><div class="aln-det"></div></div></div></div>`);
    rows.appendChild(l.el); const b = $('.aln-row', l.el), f = $('.fold', l.el);
    b.onclick = () => { const s = f.classList.toggle('shut'); b.setAttribute('aria-expanded', !s); };
  });
  const TAG = { queued:'<span class="tag">Queued</span>', waiting:`<span class="tag">${I('clock','xs')}Waiting</span>`, working:'<span class="tag aln-tg"><span class="spin"></span>Working</span>', paused:'<span class="tag warn">Paused</span>', done:`<span class="tag ok">${I('check','xs')}Done</span>` };
  const state = (l, s) => { l.el.dataset.s = s; const t = $('.aln-st', l.el); t.innerHTML = TAG[s]; enter(t.firstElementChild); };
  const act = (l, t, live) => { const a = $('.aln-a', l.el); a.classList.toggle('live', !!live); a.classList.toggle('shim', !!live); swap(a, t); };
  let paused = false, secs = 0, finished = false, steps = 0;
  const count = () => swap(ct, `${steps} of ${STEPS} steps`);
  const pb = $('.aln-pause', r);
  pb.onclick = () => { paused = !paused; pb.innerHTML = I(paused ? 'play' : 'pause','xs') + (paused ? 'Resume' : 'Pause all'); swap($('.aln-t', r), paused ? 'All agents paused' : '3 agents working');
    L.forEach(l => { if (l.running){ state(l, paused ? 'paused' : 'working'); $('.aln-a', l.el).classList.toggle('shim', !paused); } }); };
  c.every(1000, () => { if (!paused && !finished){ secs++; $('.aln-m', r).textContent = Math.floor(secs / 60) + ':' + String(secs % 60).padStart(2, '0'); } });
  // time only passes for the agents while they aren't paused; each() hears how far through the wait they are
  const hold = async (ms, each) => { let t = 0; while (t < ms){ await c.wait(100); if (!paused){ t += 100; each && each(t / ms); } } };
  async function work(l){
    l.running = true; state(l, 'working');
    const bars = $$('.aln-tr i', l.el), det = $('.aln-det', l.el);
    for (let i = 0; i < 3; i++){
      bars[i].classList.add('run'); act(l, l.acts[i], true);
      await hold(1500, p => bars[i].style.setProperty('--p', p.toFixed(3)));
      bars[i].classList.replace('run', 'on'); steps++; count();
      const d = html(`<div><span>${l.log[i]}</span><span class="muted">${secs}s</span></div>`); det.appendChild(d); enter(d);
    }
    l.running = false; act(l, l.log[2]); state(l, 'done');
  }
  // a light runs down the relay line from one badge to the next, the badge it reaches rings, and the stretch stays lit
  function carry(from, to){
    const rr = rows.getBoundingClientRect(), a = $('.aln-av', from.el).getBoundingClientRect(), b = $('.aln-av', to.el).getBoundingClientRect();
    const pk = html(`<span class="aln-pk" aria-hidden="true" style="--from:var(--${from.t});--to:var(--${to.t})"></span>`); rows.appendChild(pk);
    const y0 = a.bottom - rr.top + 4, y1 = b.top - rr.top - 4;
    const an = REDUCE ? null : pk.animate([{ transform:`translateY(${y0}px)`, opacity:0 }, { opacity:1, offset:.12 }, { opacity:1, offset:.88 }, { transform:`translateY(${y1}px)`, opacity:0 }], { duration:950, easing:'cubic-bezier(.65,0,.35,1)' });
    c.offs.push(() => pk.remove());
    return (an ? an.finished.catch(() => {}) : Promise.resolve()).then(() => pk.remove());
  }
  async function handoff(from, to, txt){
    const h = html(`<div class="fold shut aln-hf" style="--from:var(--${from.t});--to:var(--${to.t})"><div><div class="aln-hand"><b class="f">${from.n}</b> handed ${txt} to <b class="t">${to.n}</b></div></div></div>`);
    to.el.before(h); void h.offsetWidth; h.classList.remove('shut'); enter($('.aln-hand', h), 80);
    await c.wait(REDUCE ? 0 : 500); await carry(from, to);
    from.el.classList.add('sent'); h.classList.add('lit'); to.el.classList.add('got');
    const av = $('.aln-av', to.el); av.classList.add('ping'); c.later(950, () => av.classList.remove('ping'));
    await c.wait(1300); h.classList.add('shut'); await c.wait(REDUCE ? 0 : 700); h.remove();
  }
  c.run(async () => {
    await c.wait(600);
    const r1 = work(L[0]); act(L[1], L[1].wait); state(L[1], 'waiting');
    await r1; await handoff(L[0], L[1], 'the brief');
    act(L[2], L[2].wait); state(L[2], 'waiting');
    await work(L[1]); await handoff(L[1], L[2], '4 frames');
    await work(L[2]);
    finished = true; root.classList.add('fin'); $('.aln-ic', r).innerHTML = I('ok'); enter($('.aln-ic', r).firstElementChild);
    swap($('.aln-t', r), 'All 3 agents finished'); pb.remove();
  });
});
